var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

if (app.Environment.IsDevelopment())
{
    app.UseDeveloperExceptionPage();
}
else
{
    app.UseExceptionHandler("/Home/Error");
    app.UseHsts();
}

app.UseHttpsRedirection();
app.UseStaticFiles();
app.UseRouting();
app.MapControllers();
app.Run();

// Program.cs
if (!app.Environment.IsDevelopment())
{
    app.UseExceptionHandler("/Home/Error");
    app.UseHsts();
}

// HomeController.cs
public class HomeController : Controller
{
    private readonly ILogger<HomeController> _logger;

    public IActionResult Error()
    {
        var exceptionFeature = HttpContext.Features.Get<IExceptionHandlerFeature>();
        var exception = exceptionFeature?.Error;

        if (exception != null)
        {
            _logger.LogError(exception, "An unhandled exception occurred.");
        }

        return View(new ErrorViewModel { Message = "Something went wrong." });
    }
}

// Plain text response for 404 and 500
app.UseStatusCodePages(
    "text/plain", "Status Code: {0}");

// Redirect to a dedicated error page
app.UseStatusCodePagesWithRedirects("/Error/{0}");

// Re-execute the request pipeline on a different path
app.UseStatusCodePagesWithReExecute("/Error/{0}");

public class ApiExceptionFilter : IExceptionFilter
{
    private readonly ILogger<ApiExceptionFilter> _logger;
    private readonly IWebHostEnvironment _env;

    public ApiExceptionFilter(
        ILogger<ApiExceptionFilter> logger,
        IWebHostEnvironment env)
    {
        _logger = logger;
        _env = env;
    }

    public void OnException(ExceptionContext context)
    {
        _logger.LogError(context.Exception, "Unhandled exception");

        context.Result = new JsonResult(new
        {
            StatusCode = 500,
            Message = _env.IsDevelopment()
                ? context.Exception.Message
                : "An internal server error occurred.",
            Detail = _env.IsDevelopment()
                ? context.Exception.StackTrace
                : null
        })
        {
            StatusCode = StatusCodes.Status500InternalServerError
        };

        context.ExceptionHandled = true;
    }
}

// Register globally in Program.cs
builder.Services.AddControllers(options =>
{
    options.Filters.Add<ApiExceptionFilter>();
});
